import React, { Component } from 'react'
import StepWrapper from '../components/Step'
import { Row, Col, Button, notification, Form } from 'antd'
import Step3Wrapper from '../index'
import { get } from 'lodash'
import { connect } from 'react-redux'
import Step3Actions from '../../../../../../redux/productConfig/actions'
import { errorSectionCheck } from '../../../../constants/payloadWrapper'
import { errorHandler } from '../../../../components/formItem'
import { localStorageCheck, removeLocalStorage } from '../../../../util/localstorageCheck'
import CollapseWrapper from '../components/PacakageComponent'
import { setFormFieldsDataFunction, payloadFormationFunction, packagePayloadFormation, initialValidationData } from './commanFunctions'
import PackageStyleWrapper from './index.style'
import moment from 'moment'

const {
  resetProductConfigRedux,
  addPackage,
  getAllProductValidations
} = Step3Actions
class PackageInfo extends Component {
  // This is main page
  state = {
    currentPanelState: ['1'],
    nextButtonEnabled: false,
    activePanels: {
      1: true
    },
    step1Data: {},
    packageData: {},
    routedPage: '',
    step2Data: {},
    validationData: [],
    initialData: [],
    newStep: {
      provider: false,
      endorsement: false
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      addProductPackagesMessageField,
      addProductPackagesMessageFieldError,
      productValidationMesage,
      productValidation
    } = nextProps
    if (addProductPackagesMessageField === 'success') {
      notification.success({
        message: 'Success',
        description: 'Package Created SuccessFully'
      })
      this.props.resetProductConfigRedux(['addProductPackagesMessage'])
      this.nextPageHandler()
    }
    if (productValidationMesage === 'success') {
      this.setState({
        validationData: get(productValidation, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['getAllProductValidationMessage'])
    }
    errorHandler.call(this, {
      submitError: addProductPackagesMessageFieldError,
      detailMessage: addProductPackagesMessageField,
      resetFunction: () => this.props.resetProductConfigRedux(['addProductPackagesMessage'])
    })
    // if (addProductPackagesMessageField !== 'success' && addProductPackagesMessageField !== undefined) {
    //   notification['error']({
    //     message: 'Error',
    //     description: 'Package Not Created'
    //   })
    //   this.props.resetProductConfigRedux(['addProductPackagesMessageField'])
    // }
  }

  componentDidMount () {
    const { location } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'detail-page-new-package': {
        const formData = get(location, 'state.formData', {})
        const step1Data = get(formData, 'step1Data', {})
        const step2Data = get(formData, 'step2Data', {})
        this.setState({
          step1Data,
          step2Data,
          routedPage: 'detail-page'
        })
      }
        break
      case 'package-table': {
        const formData = get(location, 'state.formData', {})
        const step1Data = get(formData, 'step1Data', {})
        // const step2Data = get(formData, 'step2Data', )
        this.setState({
          step1Data,
          routedPage: 'table'
        })
        this.props.getAllProductValidations()
      }
        break
      case 'validation-table': {
        const step1Data = get(location, 'state.formData.step1Data', {})
        const formData = get(location, 'state.formData.packageData', {})
        const step2Data = get(location, 'state.formData.step2Data', {})
        const initialData = get(location, 'state.formData.initialData', [])
        const totlaPanels = ['1', '2', '3', '4', '5', '6']
        let activePanels = {}
        totlaPanels.forEach(item => {
          activePanels = {
            ...activePanels,
            [item]: true
          }
        })
        this.setState({
          routedPage: 'validation',
          currentPanelState: totlaPanels,
          activePanels: activePanels,
          nextButtonEnabled: true,
          step1Data,
          step2Data,
          packageData: packagePayloadFormation(formData) || {},
          initialData
        })
      }

        break
      default: {
        this.props.history.push({
          pathname: '/product-config/create-product/1'
        })
      }
    }
    // TODO: for checking data coming from validation to make it next button enabled
    // const buttonEnabled = get(location, 'state.nextButtonEnabled', false)
    // if (buttonEnabled) {
    //   this.setState({
    //     nextButtonEnabled: true
    //   })
    // }
  }

  nextPageHandler = () => {
    const { routedPage, step1Data, packageData } = this.state
    const { history } = this.props
    if (routedPage === 'detail-page') {
      history.goBack()
    } else {
      const data = localStorageCheck(window.sessionStorage.getItem('Step2'))
      const initialValidation = initialValidationData(data, this.state.validationData, get(packageData, 'code'))
      history.push({
        pathname: '/product-config/create-product/3/data-validation',
        state: {
          formName: 'package-info',
          formData: {
            initialData: initialValidation.length > 0 ? initialValidation : [],
            step1Data: step1Data,
            step2Data: localStorageCheck(window.sessionStorage.getItem('Step2')),
            packageData: packageData
          }
        }
      })
    }
  }

  handleOnChangePannel = (key) => {
    this.setState({
      currentPanelState: key
    }, () => {
      const { activePanels } = this.state

      const data = { ...activePanels }

      if (!this.state.nextButtonEnabled) {
        key.forEach(item => {
          const accordianNumber = Number(item)
          if (!(accordianNumber in data)) {
            data[accordianNumber] = true
          }
        })
        this.setState({
          activePanels: data
        })
        const mandatoryAccordian = [1, 2, 3, 4, 5]
        const counter = []
        Object.keys(data).forEach(item => {
          if (mandatoryAccordian.includes(Number(item))) {
            counter.push(item)
          }
        })
        if (counter.length === mandatoryAccordian.length) {
          this.setState({
            nextButtonEnabled: true
          })
        }
      }
    })
  }

  disabledNextButton = (type = '') => {
    this.setState({
      nextButtonEnabled: type === 'true'
    })
  }

  handlePreviousPageHandler = () => {
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/3',
      state: {
        formName: 'package-info',
        formData: {
          step1Data: this.state.step1Data,
          step2Data: this.state.step2Data
        }
      }
    })
  }

  setFormFieldsData = (object) => {
    const newLocalStorage = setFormFieldsDataFunction(object, this) || {}
    const data = payloadFormationFunction(newLocalStorage, this.state.step1Data)
    const URLS = data.policy_creation_wording_urls
    const endorsementURL = data.policy_endorsement_wording_urls
    data.policy_creation_wording_urls = Array.isArray(URLS) ? URLS.join(',') : URLS
    data.policy_endorsement_wording_urls = Array.isArray(endorsementURL) ? endorsementURL.join(',') : endorsementURL
    const productCodeObject = this.state.step1Data
    this.setState({
      packageData: data
    })
    this.props.addPackage({ query: { productCode: get(productCodeObject, 'code', '') }, body: data })
  }

  handleSubmit = (e) => {
    e.preventDefault()
    const { routedPage } = this.state
    if (routedPage === 'validation') {
      // If user went back to this page from validation page
      this.props.history.push({
        pathname: '/product-config/create-product/3/data-validation',
        state: {
          formName: 'package-info',
          formData: {
            initialData: this.state.initialData,
            step1Data: this.state.step1Data,
            step2Data: this.state.step2Data,
            packageData: this.state.packageData
          }
        }
      })
    } else {
      // Default submission behaviour
      const { form } = this.props

      const { setFieldsValue, getFieldsValue } = form
      const data = getFieldsValue()

      if (data?.coverage_end_static_datetime) {
        const newDate = moment(data?.coverage_end_static_datetime)?.format('YYYY-MM-DD HH:MM:SS')
        setFieldsValue({
          coverage_end_static_datetime: newDate
        })
      }
      if (data?.endorsement_coverage_end_static_datetime) {
        const newDate = moment(data?.coverage_end_static_datetime)?.format('YYYY-MM-DD HH:MM:SS')
        setFieldsValue({
          endorsement_coverage_end_static_datetime: newDate
        })
      }
      this.props.form.validateFields(async (err, values) => {
        if (!err) {
          const formBodyData = form.getFieldsValue()
          await this.setFormFieldsData(formBodyData)
        } else {
          this.setState({
            currentPanelState: [errorSectionCheck(err)]
          })
        }
      })
    }
  }

  handleCancelHandler = () => {
    this.props.history.goBack()
  }

  onhandleStepHandler = (data) => {
    this.setState({
      newStep: {
        ...this.state.newStep,
        ...data
      }
    })
  }

  componentWillUnmount () {
    window.sessionStorage.removeItem('countriesData')
    window.sessionStorage.removeItem('timezone')
    removeLocalStorage(['formData', 'Step2', 'new_premium_logic', 'configList'])
  }

  render () {
    const { currentPanelState, nextButtonEnabled, step1Data, packageData, routedPage, newStep } = this.state
    const { addProductPackagesMessageFieldError, addProductPackagesMessageFieldLoading } = this.props
    return (
      <Step3Wrapper>
        <StepWrapper
          current={0}
          newSteps={newStep}
        >
          <PackageStyleWrapper>
            <Form onSubmit={this.handleSubmit}>
              <CollapseWrapper
                history={this.props.history}
                currentStateData={this}
                step1Data={step1Data}
                form={this.props.form}
                currentPanelState={currentPanelState}
                onChangePanel={this.handleOnChangePannel}
                nextButtonEnabledFunction={this.disabledNextButton}
                editForm={false}
                packageData={packageData}
                stepHandler={this.onhandleStepHandler}
              />
              <Row type='flex' justify='center' className='button-section' gutter={30}>
                {
                  (routedPage === 'detail-page')
                    ? <Col> <Button onClick={this.handleCancelHandler}>Cancel</Button></Col>
                    : <Col> <Button onClick={this.handlePreviousPageHandler}>Previous</Button></Col>
                }
                <Col>
                  <Button
                    type='primary'
                    htmlType='submit'
                    loading={!addProductPackagesMessageFieldError && addProductPackagesMessageFieldLoading}
                    disabled={!nextButtonEnabled}
                  >
                    Next
                  </Button>
                </Col>
              </Row>
            </Form>
          </PackageStyleWrapper>
        </StepWrapper>
      </Step3Wrapper>
    )
  }
}
const WrapperWizard = Form.create()(PackageInfo)
export default connect(
  state => ({
    productValidation: state.ProductConfigurable.getAllProductValidation,
    productValidationMesage: state.ProductConfigurable.getAllProductValidationMessage,
    addProductPackagesMessageField: state.ProductConfigurable.addProductPackagesMessage,
    addProductPackagesMessageFieldError: state.Error.ADD_PACKAGE,
    addProductPackagesMessageFieldLoading: state.Loading.ADD_PACKAGE
  }), {
    resetProductConfigRedux,
    addPackage,
    getAllProductValidations
  }
)(WrapperWizard)
